mapper.select:
SELECT DISTINCT m.monomer_id, m.name, m.serial_number, m.specification, m.length, m.material, m.net_weight, m.gross_weight, m.drawing_number FROM `tech_machine_part` AS m WHERE m.bool_delete_enum = 0 AND m.monomer_id = #{monomerId}
AND m.serial_number like concat('%',#{serialNumber},'%')
AND m.relation_type = 2 ORDER BY m.serial_number ASC

select mp.*, ampl.quantity link_quantity, ampl.artifact_id, ampl.id linkId from tech_artifact_machine_part_link as ampl, tech_machine_part as mp where ampl.machine_part_id = mp.id and ampl.bool_delete_enum = 0 and mp.bool_delete_enum = 0 and ampl.artifact_id = #{artifactId}
and mp.serial_number like concat('%',#{serialNumber},'%')
and mp.quantity > 0 order by mp.bool_send_directly desc, mp.id asc

select mp.*,ampl.quantity link_quantity,ampl.artifact_id,ampl.id linkId from tech_artifact_machine_part_link as ampl, tech_machine_part as mp where ampl.machine_part_id = mp.id and ampl.bool_delete_enum = 0 and mp.bool_delete_enum = 0
and ampl.artifact_id in
#{item}

SELECT b.*,
b.monomer_id 'monomer.id',
m.name 'monomer.name',
b.area_id 'area.id',
a.name 'area.name'
FROM tech_machine_part as b
INNER JOIN sys_steel_classification ssc ON b.steel_id = ssc.id AND ssc.bool_delete_enum = 0 AND ssc.basic_class in(1,2)
left join plan_monomer m on b.monomer_id = m.id and m.bool_delete_enum = 0
left join plan_area a on b.area_id = a.id and a.bool_delete_enum = 0
where b.bool_delete_enum = 0

    and b.project_id = #{projectId}


    and b.monomer_id = #{monomerId}


    and b.area_id = #{areaId}


    and b.area_batch_id = #{areaBatchId}


    AND b.bool_status_enum = #{status}


    And b.type = #{type}


    AND b.serial_number like concat('%',#{serialNumber},'%')


    AND b.specification like concat('%',#{specification},'%')


    AND b.material = #{material}


    AND b.thick = #{thick}


    
        AND b.steel_plate_type_enum = #{steelPlateTypeEnum}
    

order by b.bool_send_directly desc, b.id asc

SELECT b.*,
b.monomer_id monomerId,
m.name monomerName,
b.area_id areaId,
a.name areaName,
batch.name areaBatchName
FROM tech_machine_part as b
INNER JOIN sys_steel_classification ssc ON b.steel_id = ssc.id AND ssc.bool_delete_enum = 0 AND ssc.basic_class in (1,2)
left join plan_monomer m on b.monomer_id = m.id and m.bool_delete_enum = 0
left join plan_area a on b.area_id = a.id and a.bool_delete_enum = 0
left join plan_area_batch batch on b.area_batch_id = batch.id and batch.bool_delete_enum = 0
where b.bool_delete_enum = 0

    and b.project_id = #{projectId}


    and b.monomer_id = #{monomerId}


    and b.area_id = #{areaId}


    and b.area_batch_id = #{areaBatchId}


    AND b.bool_status_enum = #{status}


    And b.type = #{type}


    AND b.serial_number like concat('%',#{serialNumber},'%')


    AND b.specification like concat('%',#{specification},'%')


    AND b.material = #{material}


    AND b.thick = #{thick}


    
        AND b.steel_plate_type_enum = #{steelPlateTypeEnum}
    

order by b.bool_send_directly desc, b.id asc

select m.`id` 'monomer.id', m.`name` 'monomer.name', ifnull(sum(a.quantity), 0) quantity, ROUND( ifnull( sum( a.surface_area * a.quantity ), 0 ) / 1000000, 4 ) AS total_area, ifnull(sum(a.total_net_weight), 0) total_net_weight, ifnull(sum(a.total_gross_weight), 0) total_gross_weight from tech_machine_part a inner join plan_monomer m on m.id = a.monomer_id and m.bool_delete_enum = 0
INNER JOIN sys_monomer_user_link AS link ON a.monomer_id = link.monomer_id AND link.bool_delete_enum = 0 AND link.deepened_person_id = #{userId}
where a.bool_delete_enum = 0 and a.relation_type in (2, 16) and a.project_id = #{projectId} group by m.id, m.name

select d.`id` 'area.id', d.`name` 'area.name', ifnull(sum(a.quantity), 0) quantity, ROUND( ifnull( sum( a.surface_area * a.quantity ), 0 ) / 1000000, 4 ) AS total_area, ifnull(sum(a.total_net_weight), 0) total_net_weight, ifnull(sum(a.total_gross_weight), 0) total_gross_weight from tech_machine_part a inner join plan_area d on d.id = a.area_id and d.bool_delete_enum = 0
INNER JOIN sys_monomer_user_link AS link ON a.monomer_id = link.monomer_id AND link.bool_delete_enum = 0 AND link.deepened_person_id = #{userId}
where a.bool_delete_enum = 0 and a.relation_type in (2, 16) and a.monomer_id = #{monomerId} group by d.id, d.name

SELECT *
FROM `tech_machine_part`
WHERE bool_delete_enum = 0
AND steel_id = #{steelId}

    AND spec_prefix = #{specPrefix}

LIMIT 1

SELECT
m.project_id,
m.monomer_id,
m.area_id,
m.area_batch_id,
m.thick, m.material, SUM( m.quantity ) quantity, SUM( m.total_net_weight ) total_net_weight FROM `tech_machine_part` m INNER JOIN sys_steel_classification ssc ON m.steel_id = ssc.id AND ssc.bool_delete_enum = 0 AND ssc.basic_class in(1,2)
INNER JOIN sys_monomer_user_link AS link ON m.monomer_id = link.monomer_id AND link.bool_delete_enum = 0 AND link.deepened_person_id = #{userId}
WHERE m.bool_delete_enum = 0
AND m.project_id = #{projectId}
AND m.monomer_id = #{monomerId}
AND m.area_id = #{areaId}
AND m.area_batch_id = #{areaBatchId}
AND m.steel_plate_type_enum = #{steelPlateTypeEnum}
GROUP BY
m.project_id,
m.monomer_id,
m.area_id,
m.area_batch_id,
thick, m.material HAVING thick IS NOT NULL ORDER BY thick ASC

SELECT m.id, cp.name as projectname, cp.id AS projectid, m.thick, pa.`name` AS areaname, pa.id AS areaid, batch.id AS areaBatchId, batch.name AS areaBatchName, pm.name AS monomername, pm.id AS monomerid, m.relation_type, m.material, m.quantity AS quantity, m.total_net_weight AS total_net_weight FROM tech_machine_part m INNER JOIN sys_steel_classification ssc ON m.steel_id = ssc.id INNER JOIN contract_project cp ON cp.id = m.project_id INNER JOIN plan_area pa ON pa.id = m.area_id INNER JOIN plan_monomer pm ON m.monomer_id = pm.id INNER JOIN plan_area_batch batch ON m.area_batch_id = batch.id AND ssc.bool_delete_enum = 0 AND ssc.basic_class in(1,2) WHERE m.bool_delete_enum = 0
AND m.project_id = #{projectId}
AND m.monomer_id = #{monomerId}
AND m.area_id = #{areaId}
AND m.area_batch_id = #{areaBatchId}
AND m.steel_plate_type_enum = #{steelPlateTypeEnum}
HAVING thick IS NOT NULL ORDER BY thick ASC

select ampl.artifact_id 'id', ampl.machine_part_id 'assembleOrPartid', ampl.quantity 'scale', mp.produced_quantity 'producedQuantity', (mp.produced_quantity-mp.used_quantity )DIV ampl.quantity 'complete' from tech_artifact_machine_part_link as ampl, tech_machine_part as mp where ampl.machine_part_id = mp.id and ampl.bool_delete_enum = 0 AND mp.bool_process=1 and mp.bool_delete_enum = 0
and ampl.artifact_id in
#{item}
